<?php
session_start();require_once __DIR__.'/config.php';require_role('viewer');$pdo=db();$me=current_user();
$total=(int)$pdo->query("SELECT COUNT(*) FROM logbook")->fetchColumn();$today=(int)$pdo->query("SELECT COUNT(*) FROM logbook WHERE DATE(waktu_mulai)=CURDATE()")->fetchColumn();$alat=(int)$pdo->query("SELECT COUNT(*) FROM alat WHERE aktif=1")->fetchColumn();$rusak=(int)$pdo->query("SELECT COUNT(*) FROM alat WHERE aktif=1 AND kondisi_alat='Rusak'")->fetchColumn();
$due=(int)$pdo->query("SELECT COUNT(*) FROM alat WHERE aktif=1 AND tanggal_kalibrasi IS NOT NULL AND DATE_ADD(tanggal_kalibrasi,INTERVAL interval_kalibrasi_bulan MONTH) BETWEEN CURDATE() AND DATE_ADD(CURDATE(),INTERVAL 30 DAY)")->fetchColumn();
$expired=(int)$pdo->query("SELECT COUNT(*) FROM alat WHERE aktif=1 AND ((tanggal_kalibrasi IS NOT NULL AND DATE_ADD(tanggal_kalibrasi,INTERVAL interval_kalibrasi_bulan MONTH)<CURDATE()) OR status_kalibrasi='Kadaluarsa')")->fetchColumn();
$recent=$pdo->query("SELECT l.*,a.nama_alat,a.kode_alat FROM logbook l JOIN alat a ON a.id=l.alat_id ORDER BY l.waktu_mulai DESC LIMIT 8")->fetchAll();
$alerts=$pdo->query("SELECT kode_alat,nama_alat,lokasi,tanggal_kalibrasi,interval_kalibrasi_bulan,DATE_ADD(tanggal_kalibrasi,INTERVAL interval_kalibrasi_bulan MONTH) AS jatuh_tempo FROM alat WHERE aktif=1 AND tanggal_kalibrasi IS NOT NULL AND DATE_ADD(tanggal_kalibrasi,INTERVAL interval_kalibrasi_bulan MONTH)<=DATE_ADD(CURDATE(),INTERVAL 30 DAY) ORDER BY jatuh_tempo ASC LIMIT 6")->fetchAll();
function calbadge($r){$d=$r['jatuh_tempo'];if(!$d)return ['belum','Belum ada'];if($d<date('Y-m-d'))return ['kadaluarsa','Kadaluarsa'];if($d<=date('Y-m-d',strtotime('+30 days')))return ['belum','Segera jatuh tempo'];return ['terkalibrasi','Aman'];}
?><!doctype html><html lang="id"><head>
<meta name="lab-user" content="<?= isset($_SESSION['user_id']) ? (int)$_SESSION['user_id'] : 'guest' ?>">
<link rel="manifest" href="/mobile/manifest.webmanifest">
<meta name="theme-color" content="#17365d">
<script defer src="/mobile/mobile.js"></script><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dashboard | LAB Manager</title><link rel="stylesheet" href="assets/style.css"></head><body><div class="app-shell"><?php include __DIR__.'/sidebar.php';?><main class="container"><div class="pagehead"><div><div class="eyebrow">Laboratory Management System</div><h1>Dashboard</h1><p>Panel kendali operasional, inventaris, dan kepatuhan kalibrasi.</p></div><?php if(can_manage_operations()):?><a class="btn primary" href="logbook.php?new=1">＋ Catat Penggunaan</a><?php endif;?></div>
<section class="cards"><div class="card"><span class="metric">Total Logbook</span><b class="metric-value"><?=$total?></b><span class="metric-note">Seluruh pencatatan</span></div><div class="card"><span class="metric">Hari Ini</span><b class="metric-value"><?=$today?></b><span class="metric-note">Penggunaan alat</span></div><div class="card"><span class="metric">Alat Aktif</span><b class="metric-value"><?=$alat?></b><span class="metric-note"><?=$rusak?> perlu perhatian</span></div><div class="card"><span class="metric">Kalibrasi</span><b class="metric-value"><?=$due?></b><span class="metric-note"><?=$expired?> sudah lewat jatuh tempo</span></div></section>
<?php if($alerts):?><section class="panel"><div class="panelhead"><h2>⚠ Pengingat Kalibrasi</h2><a href="alat.php?filter=kalibrasi">Kelola Data Alat →</a></div><div class="warning-list"><?php foreach($alerts as $a):$cb=calbadge($a);?><div class="warning"><div><strong><?=e($a['kode_alat'])?> · <?=e($a['nama_alat'])?></strong><small><?=e($a['lokasi'])?> · Jatuh tempo <?=date('d/m/Y',strtotime($a['jatuh_tempo']))?></small></div><span class="badge <?=$cb[0]?>"><?=e($cb[1])?></span></div><?php endforeach;?></div></section><?php endif;?>
<section class="panel"><div class="panelhead"><h2>Aktivitas Terbaru</h2><a href="laporan.php">Lihat laporan →</a></div><div class="tablewrap"><table><thead><tr><th>Waktu</th><th>Kode</th><th>Alat</th><th>Operator</th><th>Kondisi</th><th>Kegiatan</th></tr></thead><tbody><?php foreach($recent as $r):?><tr><td><?=date('d/m/Y H:i',strtotime($r['waktu_mulai']))?></td><td><b><?=e($r['kode_alat'])?></b></td><td><?=e($r['nama_alat'])?></td><td><?=e($r['nama_operator'])?></td><td><span class="badge <?=strtolower($r['kondisi'])==='rusak'?'rusak':(strtolower($r['kondisi'])==='baik'?'baik':'catatan')?>"><?=e($r['kondisi'])?></span></td><td><?=e($r['tujuan'])?></td></tr><?php endforeach;?><?php if(!$recent):?><tr><td colspan="6" class="empty">Belum ada aktivitas.</td></tr><?php endif;?></tbody></table></div></section>
</main></div></body></html>
